// Ops Health Monitor - Evaluate Health (T0: deterministic, no LLM)
// Inputs: Config + 4 read-only GET probes. Output: 0..n Telegram messages ({ text, kind }).
const cfg = $('Config').first().json;
const nowMs = Date.now();
let isSummary = false;
try { isSummary = $('Daily 08:00 Summary').isExecuted === true; } catch (e) { isSummary = false; }
const SUPPRESS_MS = Number(cfg.suppress_hours || 2) * 3600000;

function redact(value, max) {
  let s = String(value == null ? '' : value);
  const rules = [
    [/\b\d{6,12}:[A-Za-z0-9_-]{30,}/g, '[REDACTED_TELEGRAM_TOKEN]'],
    [/\bgithub_pat_[A-Za-z0-9_]{20,}/g, '[REDACTED_GITHUB_TOKEN]'],
    [/\bgh[pousr]_[A-Za-z0-9]{20,}/g, '[REDACTED_GITHUB_TOKEN]'],
    [/\bsk-[A-Za-z0-9_-]{16,}/g, '[REDACTED_API_KEY]'],
    [/\beyJ[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}\.[A-Za-z0-9_-]{5,}/g, '[REDACTED_JWT]'],
    [/\b(bearer|basic)\s+[A-Za-z0-9._~+\/=-]{8,}/gi, '$1 [REDACTED]'],
    [/((?:api[_-]?key|x-n8n-api-key|access[_-]?token|token|secret|password|passwd|authorization)["']?\s*[:=]\s*["']?)(?!\[REDACTED)[^\s"',;&]+/gi, '$1[REDACTED]'],
    [/(\/\/[^\/\s:@]+:)[^@\s\/]+@/g, '$1[REDACTED]@'],
  ];
  for (const r of rules) s = s.replace(r[0], r[1]);
  if (max && s.length > max) s = s.slice(0, max) + '...';
  return s;
}
function escapeHtml(s) {
  return String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
}
function riyadh(ms) {
  return new Date(ms + 3 * 3600000).toISOString().slice(0, 16).replace('T', ' ') + ' (الرياض)';
}
function resp(name) {
  try { const it = $(name).first(); return it ? it.json : null; } catch (e) { return null; }
}
function ok(r) {
  return !!r && Number(r.statusCode) >= 200 && Number(r.statusCode) < 300;
}
function describe(r) {
  if (!r) return 'لا استجابة';
  if (r.statusCode) return 'HTTP ' + r.statusCode;
  if (r.error) return redact(r.error.message || r.error, 200);
  return 'استجابة غير متوقعة';
}

const apiProbe = resp('Check API Health');
const wfResp = resp('Get Workflows');
const failResp = resp('Get Failed Executions');
const hbResp = resp('Get Heartbeat Executions');

const issues = [];
function add(key, severity, text) { issues.push({ key: key, severity: severity, text: redact(text, 400) }); }

// Which categories could actually be evaluated this run (prevents false "recovered").
const evaluated = { api: true, wf: false, hb: false, fail: false };

// 1) n8n / API health
if (!ok(apiProbe)) add('api:healthz', 'critical', 'n8n لا يستجيب لفحص /healthz (' + describe(apiProbe) + ')');
if (!ok(wfResp)) add('api:workflows', 'critical', 'تعذّرت قراءة قائمة المسارات عبر n8n API (' + describe(wfResp) + ')');
if (!ok(failResp)) add('api:executions', 'critical', 'تعذّرت قراءة سجل التنفيذات عبر n8n API (' + describe(failResp) + ')');

const workflows = ok(wfResp) && wfResp.body && Array.isArray(wfResp.body.data) ? wfResp.body.data : null;
const expected = Array.isArray(cfg.expected_workflows) ? cfg.expected_workflows : [];
// Empty heartbeat_workflow_name = heartbeat check disabled (no heartbeat workflow in this project yet).
const hbName = String(cfg.heartbeat_workflow_name || '').trim();

// 2) Expected workflows exist and are active
if (workflows) {
  evaluated.wf = true;
  for (const name of expected) {
    const wf = workflows.find(function (w) { return w.name === name && !w.isArchived; });
    if (!wf) add('wf:missing:' + name, 'high', 'المسار المتوقع غير موجود: ' + name);
    else if (!wf.active) add('wf:inactive:' + name, 'high', 'المسار المتوقع غير مفعّل: ' + name);
  }
}

// 3) Heartbeat freshness
if (workflows && hbName) {
  const hbWf = workflows.find(function (w) { return w.name === hbName && !w.isArchived; });
  if (!hbWf) {
    evaluated.hb = true;
    if (expected.indexOf(hbName) === -1) add('hb:missing', 'high', 'مسار النبضة غير موجود: ' + hbName);
  } else if (!ok(hbResp)) {
    add('api:heartbeat', 'critical', 'تعذّرت قراءة تنفيذات مسار النبضة (' + describe(hbResp) + ')');
  } else {
    evaluated.hb = true;
    const last = ((hbResp.body && hbResp.body.data) || [])[0];
    const maxMin = Number(cfg.heartbeat_max_age_minutes || 30);
    if (!last) {
      add('hb:stale', 'high', 'لا يوجد أي تنفيذ ناجح لمسار النبضة ' + hbName);
    } else {
      const lastMs = Date.parse(last.stoppedAt || last.startedAt);
      const ageMin = Math.round((nowMs - lastMs) / 60000);
      if (isNaN(lastMs) || ageMin > maxMin) {
        add('hb:stale', 'high', 'تأخرت النبضة: آخر تنفيذ ناجح لـ ' + hbName + ' منذ ' + ageMin + ' دقيقة (الحد ' + maxMin + ' دقيقة)');
      }
    }
  }
}

// 4) Failures not covered by an error workflow
if (workflows && ok(failResp)) {
  evaluated.fail = true;
  const byId = {};
  workflows.forEach(function (w) { byId[w.id] = w; });
  const lookback = Number(cfg.failure_lookback_minutes || 15);
  const recent = ((failResp.body && failResp.body.data) || []).filter(function (e) {
    return nowMs - Date.parse(e.startedAt) <= lookback * 60000;
  });
  const groups = {};
  for (const e of recent) {
    const wf = byId[e.workflowId];
    const covered = !!(wf && wf.settings && wf.settings.errorWorkflow);
    if (covered) continue;
    (groups[e.workflowId] = groups[e.workflowId] || []).push(e);
  }
  for (const id of Object.keys(groups)) {
    const list = groups[id];
    const name = byId[id] ? byId[id].name : id;
    add('fail:uncovered:' + id, 'high', 'إخفاقات غير مغطاة بمعالج أخطاء في "' + name + '": ' + list.length + ' خلال آخر ' + lookback + ' دقيقة (آخرها التنفيذ #' + list[0].id + ')');
  }
}

function category(key) {
  const p = key.split(':')[0];
  return p === 'api' ? 'api' : p;
}

const out = [];
const stamp = riyadh(nowMs);

if (isSummary) {
  // Daily summary: always sent, does not touch dedup state.
  const lines = ['ملخص الصحة اليومي - ' + stamp, ''];
  if (issues.length === 0) {
    lines.push('الحالة: كل الفحوصات سليمة.');
  } else {
    lines.push('الحالة: ' + issues.length + ' مشكلة قائمة:');
    issues.forEach(function (i) { lines.push('- [' + i.severity + '] ' + i.text); });
  }
  lines.push('');
  lines.push('المسارات المتوقعة: ' + (evaluated.wf ? expected.length + ' مفحوصة' : 'تعذّر الفحص'));
  lines.push(hbName ? 'النبضة (' + hbName + '): ' + (evaluated.hb ? 'مفحوصة' : 'تعذّر الفحص') : 'النبضة: معطّلة (لا يوجد مسار نبضة مُعرّف في Config)');
  lines.push('الإخفاقات غير المغطاة: ' + (evaluated.fail ? 'مفحوصة' : 'تعذّر الفحص'));
  out.push({ kind: 'summary', text: lines.join('\n') });
} else {
  const state = $getWorkflowStaticData('global');
  if (!state.opsHealth) state.opsHealth = { active: {} };
  const active = state.opsHealth.active;
  const toSend = [];
  for (const i of issues) {
    const prev = active[i.key];
    if (!prev) {
      active[i.key] = { since: nowMs, lastNotified: nowMs, text: i.text };
      toSend.push(i);
    } else if (nowMs - prev.lastNotified >= SUPPRESS_MS) {
      prev.lastNotified = nowMs;
      prev.text = i.text;
      toSend.push(Object.assign({ repeat: true }, i));
    } else {
      prev.text = i.text; // suppressed (within suppression window)
    }
  }
  const current = {};
  issues.forEach(function (i) { current[i.key] = true; });
  const recovered = [];
  for (const key of Object.keys(active)) {
    if (current[key]) continue;
    if (!evaluated[category(key)]) continue; // could not evaluate this run: keep state
    recovered.push({ key: key, text: active[key].text, since: active[key].since });
    delete active[key];
  }
  if (toSend.length) {
    const lines = ['تنبيه صحة التشغيل - ' + stamp, ''];
    toSend.forEach(function (i) {
      lines.push('- [' + i.severity + ']' + (i.repeat ? ' (تذكير: ما زال قائماً)' : '') + ' ' + i.text);
    });
    out.push({ kind: 'alert', text: lines.join('\n') });
  }
  if (recovered.length) {
    const lines = ['تعافى - ' + stamp, ''];
    recovered.forEach(function (r) {
      lines.push('- زال: ' + r.text + ' (استمر ' + Math.max(0, Math.round((nowMs - r.since) / 60000)) + ' دقيقة)');
    });
    out.push({ kind: 'recovered', text: lines.join('\n') });
  }
}

return out.map(function (m) {
  return { json: { kind: m.kind, text: escapeHtml(redact(m.text)) } };
});
